public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int[] Q = new int[N];
    int[] A = new int[N];
    int[] B = new int[N];
    for (int i = 0; i < N; i++) {
        Q[i] = sc.nextInt();
    }
    for (int i = 0; i < N; i++) {
        A[i] = sc.nextInt();
    }
    for (int i = 0; i < N; i++) {
        B[i] = sc.nextInt();
    }
    int max_servings = 0;
    for (int x = 0; x <= Integer.MAX_VALUE; x++) {
        boolean possible = true;
        for (int i = 0; i < N; i++) {
            if (A[i] != 0 && Q[i] < A[i] * x) {
                possible = false;
                break;
            }
        }
        if (!possible) break;

        int y_min = Integer.MAX_VALUE;
        for (int i = 0; i < N; i++) {
            if (B[i] != 0) {
                y_min = Math.min(y_min, (Q[i] - A[i] * x) / B[i]);
            }
        }
        max_servings = Math.max(max_servings, x + y_min);
    }
    System.out.println(max_servings);
}
